"""Application settings, loaded from environment variables (prefix ``APP_``) or a .env file."""

from functools import lru_cache

from pydantic_settings import BaseSettings, SettingsConfigDict


class Settings(BaseSettings):
    model_config = SettingsConfigDict(env_prefix="APP_", env_file=".env", extra="ignore")

    database_url: str = "sqlite:///./shortener.db"
    base_url: str = "http://localhost:8000"

    code_length: int = 7
    code_max_attempts: int = 5

    max_url_length: int = 2048

    # Rate limit on link creation: N requests per window per client IP.
    rate_limit_requests: int = 30
    rate_limit_window_seconds: int = 60

    # In-process lookup cache for redirects.
    cache_ttl_seconds: int = 300
    cache_max_entries: int = 10_000

    # Destination denylist, comma-separated (e.g. "phish.example,malware.test").
    # A domain also blocks all of its subdomains.
    blocked_domains: str = ""

    @property
    def blocked_domain_set(self) -> frozenset[str]:
        return parse_domains(self.blocked_domains)


def parse_domains(raw: str) -> frozenset[str]:
    return frozenset(d.strip().lower().rstrip(".") for d in raw.split(",") if d.strip())


@lru_cache
def get_settings() -> Settings:
    return Settings()

"""Input validation for URLs and custom aliases.

Security goals:
- Only http/https targets (no javascript:, data:, file: ...).
- Refuse targets that point at loopback, private, link-local or reserved addresses, so the
  shortener cannot be used to reach internal services or cloud metadata endpoints.
- Refuse links that point back at this service (redirect loops).

Limitation: hostnames are checked literally; DNS is not resolved here, so a public name that
resolves to a private IP is not caught. A production deployment should resolve and re-check,
or enforce this at an egress proxy.
"""

import ipaddress
import re
from urllib.parse import urlsplit

ALIAS_RE = re.compile(r"^[A-Za-z0-9_-]{3,32}$")
RESERVED_ALIASES = frozenset(
    {"api", "docs", "redoc", "openapi", "health", "ready", "static", "admin"}
)
BLOCKED_HOSTNAMES = frozenset({"localhost", "localhost.localdomain", "metadata.google.internal"})


class ValidationError(ValueError):
    """Raised when user input is rejected. The message is safe to return to clients."""


def is_blocked_host(host: str, blocked: frozenset[str]) -> bool:
    """True if ``host`` is a blocked domain or a subdomain of one."""
    host = host.lower().rstrip(".")
    return any(host == d or host.endswith("." + d) for d in blocked)


def destination_is_blocked(url: str, blocked: frozenset[str]) -> bool:
    return bool(blocked) and is_blocked_host(urlsplit(url).hostname or "", blocked)


def validate_target_url(
    url: str,
    *,
    max_length: int,
    own_host: str | None = None,
    blocked_domains: frozenset[str] = frozenset(),
) -> str:
    url = url.strip()
    if not url:
        raise ValidationError("url must not be empty")
    if len(url) > max_length:
        raise ValidationError(f"url must be at most {max_length} characters")

    parts = urlsplit(url)
    if parts.scheme.lower() not in {"http", "https"}:
        raise ValidationError("only http and https urls are allowed")
    if parts.username or parts.password:
        raise ValidationError("urls with embedded credentials are not allowed")

    host = (parts.hostname or "").lower().rstrip(".")
    if not host:
        raise ValidationError("url must include a host")
    if host in BLOCKED_HOSTNAMES or host.endswith(".localhost"):
        raise ValidationError("url host is not allowed")
    if blocked_domains and is_blocked_host(host, blocked_domains):
        raise ValidationError("destination domain is blocked")
    if own_host and host == own_host.lower():
        raise ValidationError("url must not point to this service")

    try:
        ip = ipaddress.ip_address(host)
    except ValueError:
        ip = None
    if ip is not None and not ip.is_global:
        raise ValidationError("url must not point to a private or reserved address")

    return url


def validate_alias(alias: str) -> str:
    if not ALIAS_RE.fullmatch(alias):
        raise ValidationError("alias must be 3-32 characters: letters, digits, '-' or '_'")
    if alias.lower() in RESERVED_ALIASES:
        raise ValidationError("alias is reserved")
    return alias

"""Link business logic, independent of HTTP.

The API layer translates the exceptions here into status codes.
"""

import hashlib
import hmac
import json
from dataclasses import dataclass
from datetime import UTC, datetime

from sqlalchemy import func, select, update
from sqlalchemy.exc import IntegrityError
from sqlalchemy.orm import Session

from service.core.codegen import generate_code
from service.core.validation import ValidationError, validate_alias, validate_target_url
from service.db.models import ClickEvent, IdempotencyKey, Url


class LinkError(Exception):
    """Base class for domain errors."""


class AliasTakenError(LinkError):
    pass


class LinkNotFoundError(LinkError):
    pass


class LinkGoneError(LinkError):
    """The link existed but has expired or been deleted."""


class IdempotencyConflictError(LinkError):
    """The idempotency key was reused with a different request body."""


class CodeSpaceExhaustedError(LinkError):
    pass


@dataclass(frozen=True)
class CreateResult:
    url: Url
    created: bool  # False when replayed from an idempotency key


def as_utc(dt: datetime | None) -> datetime | None:
    """SQLite drops tzinfo; treat stored naive datetimes as UTC."""
    if dt is None:
        return None
    return dt if dt.tzinfo else dt.replace(tzinfo=UTC)


def _now() -> datetime:
    return datetime.now(UTC)


class LinkService:
    def __init__(
        self,
        session: Session,
        *,
        code_length: int,
        code_max_attempts: int,
        max_url_length: int,
        own_host: str | None = None,
        blocked_domains: frozenset[str] = frozenset(),
        ua_salt: str = "url-shortener",
    ) -> None:
        self.session = session
        self.code_length = code_length
        self.code_max_attempts = code_max_attempts
        self.max_url_length = max_url_length
        self.own_host = own_host
        self.blocked_domains = blocked_domains
        self._ua_salt = ua_salt.encode()

    # ---- create -------------------------------------------------------------------------

    def create(
        self,
        long_url: str,
        *,
        custom_alias: str | None = None,
        expires_at: datetime | None = None,
        idempotency_key: str | None = None,
    ) -> CreateResult:
        long_url = validate_target_url(
            long_url,
            max_length=self.max_url_length,
            own_host=self.own_host,
            blocked_domains=self.blocked_domains,
        )
        if custom_alias is not None:
            custom_alias = validate_alias(custom_alias)
        if expires_at is not None:
            expires_at = expires_at if expires_at.tzinfo else expires_at.replace(tzinfo=UTC)
            if expires_at <= _now():
                raise ValidationError("expires_at must be in the future")

        request_hash = None
        if idempotency_key:
            payload = json.dumps(
                {
                    "url": long_url,
                    "alias": custom_alias,
                    "expires_at": expires_at.isoformat() if expires_at else None,
                },
                sort_keys=True,
            )
            request_hash = hashlib.sha256(payload.encode()).hexdigest()
            existing = self.session.get(IdempotencyKey, idempotency_key)
            if existing is not None:
                if existing.request_hash != request_hash:
                    raise IdempotencyConflictError(
                        "idempotency key was already used with a different request"
                    )
                url = self._get_by_code(existing.code)
                if url is not None:
                    return CreateResult(url=url, created=False)

        url = self._insert(long_url, custom_alias, expires_at)

        if idempotency_key and request_hash:
            self.session.add(
                IdempotencyKey(key=idempotency_key, request_hash=request_hash, code=url.code)
            )
            self.session.commit()
        return CreateResult(url=url, created=True)

    def _insert(self, long_url: str, alias: str | None, expires_at: datetime | None) -> Url:
        if alias is not None:
            url = Url(code=alias, long_url=long_url, is_custom=True, expires_at=expires_at)
            self.session.add(url)
            try:
                self.session.commit()
            except IntegrityError as exc:
                self.session.rollback()
                raise AliasTakenError("alias is already in use") from exc
            return url

        for _ in range(self.code_max_attempts):
            url = Url(
                code=generate_code(self.code_length), long_url=long_url, expires_at=expires_at
            )
            self.session.add(url)
            try:
                self.session.commit()
                return url
            except IntegrityError:
                self.session.rollback()  # collision: retry with a new code
        raise CodeSpaceExhaustedError("could not allocate a unique code; try again")

    # ---- read ---------------------------------------------------------------------------

    def _get_by_code(self, code: str) -> Url | None:
        return self.session.scalar(select(Url).where(Url.code == code))

    def get(self, code: str, *, include_inactive: bool = False) -> Url:
        url = self._get_by_code(code)
        if url is None:
            raise LinkNotFoundError(code)
        if not include_inactive:
            self.ensure_active(url)
        return url

    @staticmethod
    def ensure_active(url: Url) -> None:
        if url.is_deleted:
            raise LinkGoneError("link has been deleted")
        expires_at = as_utc(url.expires_at)
        if expires_at is not None and expires_at <= _now():
            raise LinkGoneError("link has expired")

    def stats(self, code: str) -> dict:
        url = self.get(code, include_inactive=True)
        day = func.date(ClickEvent.ts)
        rows = self.session.execute(
            select(day.label("day"), func.count().label("clicks"))
            .where(ClickEvent.code == code)
            .group_by(day)
            .order_by(day)
        ).all()
        return {
            "code": url.code,
            "total_clicks": url.click_count,
            "last_accessed_at": as_utc(url.last_accessed_at),
            "clicks_by_day": [{"day": str(r.day), "clicks": r.clicks} for r in rows],
        }

    # ---- write --------------------------------------------------------------------------

    def delete(self, code: str) -> Url:
        url = self.get(code, include_inactive=True)
        if url.is_deleted:
            raise LinkGoneError("link has already been deleted")
        url.is_deleted = True
        self.session.commit()
        return url

    def record_click(self, code: str, *, referrer: str | None, user_agent: str | None) -> None:
        ua_hash = (
            hmac.new(self._ua_salt, user_agent.encode(), hashlib.sha256).hexdigest()
            if user_agent
            else None
        )
        # Atomic increment in SQL so concurrent redirects don't lose counts.
        result = self.session.execute(
            update(Url)
            .where(Url.code == code)
            .values(click_count=Url.click_count + 1, last_accessed_at=_now())
        )
        if result.rowcount == 0:
            self.session.rollback()
            return
        self.session.add(
            ClickEvent(
                code=code, referrer=referrer[:512] if referrer else None, user_agent_hash=ua_hash
            )
        )
        self.session.commit()

"""HTTP routes. Thin layer: validate input, call LinkService, map errors to status codes."""

from collections.abc import Iterator
from datetime import UTC, datetime
from urllib.parse import urlsplit

from fastapi import APIRouter, BackgroundTasks, Depends, Header, HTTPException, Request, Response
from fastapi.responses import RedirectResponse
from sqlalchemy import text
from sqlalchemy.orm import Session

from service.api.schemas import (
    CreateUrlRequest,
    ErrorResponse,
    HealthResponse,
    StatsResponse,
    UrlResponse,
)
from service.core.links import (
    AliasTakenError,
    CodeSpaceExhaustedError,
    IdempotencyConflictError,
    LinkGoneError,
    LinkNotFoundError,
    LinkService,
    as_utc,
)
from service.core.validation import ValidationError
from service.db.models import Url

api = APIRouter(prefix="/api/v1", tags=["urls"])
ops = APIRouter(tags=["ops"])
redirect = APIRouter(tags=["redirect"])


# ---- dependencies ---------------------------------------------------------------------------


def get_session(request: Request) -> Iterator[Session]:
    session = request.app.state.session_factory()
    try:
        yield session
    finally:
        session.close()


def get_link_service(request: Request, session: Session = Depends(get_session)) -> LinkService:
    s = request.app.state.settings
    return LinkService(
        session,
        code_length=s.code_length,
        code_max_attempts=s.code_max_attempts,
        max_url_length=s.max_url_length,
        own_host=urlsplit(s.base_url).hostname,
        blocked_domains=s.blocked_domain_set,
    )


def enforce_rate_limit(request: Request, response: Response) -> None:
    limiter = request.app.state.rate_limiter
    client = request.client.host if request.client else "unknown"
    if not limiter.allow(client):
        raise HTTPException(
            status_code=429,
            detail="rate limit exceeded",
            headers={"Retry-After": str(limiter.retry_after())},
        )


def to_response(url: Url, base_url: str) -> UrlResponse:
    return UrlResponse(
        code=url.code,
        short_url=f"{base_url.rstrip('/')}/{url.code}",
        long_url=url.long_url,
        created_at=as_utc(url.created_at),
        expires_at=as_utc(url.expires_at),
        is_custom=url.is_custom,
    )


NOT_FOUND = {404: {"model": ErrorResponse, "description": "Link not found"}}
GONE = {410: {"model": ErrorResponse, "description": "Link expired or deleted"}}


# ---- API ------------------------------------------------------------------------------------


@api.post(
    "/urls",
    response_model=UrlResponse,
    status_code=201,
    responses={
        200: {"model": UrlResponse, "description": "Replayed via Idempotency-Key"},
        409: {"model": ErrorResponse, "description": "Alias taken or idempotency conflict"},
        422: {"model": ErrorResponse, "description": "Invalid input"},
        429: {"model": ErrorResponse, "description": "Rate limit exceeded"},
    },
    dependencies=[Depends(enforce_rate_limit)],
)
def create_url(
    body: CreateUrlRequest,
    request: Request,
    response: Response,
    service: LinkService = Depends(get_link_service),
    idempotency_key: str | None = Header(None, alias="Idempotency-Key", max_length=128),
) -> UrlResponse:
    try:
        result = service.create(
            body.url,
            custom_alias=body.custom_alias,
            expires_at=body.expires_at,
            idempotency_key=idempotency_key,
        )
    except ValidationError as exc:
        raise HTTPException(status_code=422, detail=str(exc)) from exc
    except (AliasTakenError, IdempotencyConflictError) as exc:
        raise HTTPException(status_code=409, detail=str(exc)) from exc
    except CodeSpaceExhaustedError as exc:
        raise HTTPException(status_code=503, detail=str(exc)) from exc
    if not result.created:
        response.status_code = 200
    return to_response(result.url, request.app.state.settings.base_url)


@api.get("/urls/{code}", response_model=UrlResponse, responses={**NOT_FOUND, **GONE})
def get_url(
    code: str, request: Request, service: LinkService = Depends(get_link_service)
) -> UrlResponse:
    try:
        url = service.get(code)
    except LinkNotFoundError as exc:
        raise HTTPException(status_code=404, detail="link not found") from exc
    except LinkGoneError as exc:
        raise HTTPException(status_code=410, detail=str(exc)) from exc
    return to_response(url, request.app.state.settings.base_url)


@api.get("/urls/{code}/stats", response_model=StatsResponse, responses=NOT_FOUND)
def get_stats(code: str, service: LinkService = Depends(get_link_service)) -> StatsResponse:
    try:
        return StatsResponse(**service.stats(code))
    except LinkNotFoundError as exc:
        raise HTTPException(status_code=404, detail="link not found") from exc


@api.delete("/urls/{code}", status_code=204, responses={**NOT_FOUND, **GONE})
def delete_url(
    code: str, request: Request, service: LinkService = Depends(get_link_service)
) -> Response:
    try:
        service.delete(code)
    except LinkNotFoundError as exc:
        raise HTTPException(status_code=404, detail="link not found") from exc
    except LinkGoneError as exc:
        raise HTTPException(status_code=410, detail=str(exc)) from exc
    request.app.state.cache.invalidate(code)
    return Response(status_code=204)


# ---- ops ------------------------------------------------------------------------------------


@ops.get("/health", response_model=HealthResponse)
def health() -> HealthResponse:
    return HealthResponse(status="ok")


@ops.get(
    "/ready",
    response_model=HealthResponse,
    responses={503: {"model": ErrorResponse, "description": "Database unavailable"}},
)
def ready(session: Session = Depends(get_session)) -> HealthResponse:
    try:
        session.execute(text("SELECT 1"))
    except Exception as exc:  # noqa: BLE001 - any DB failure means not ready
        raise HTTPException(status_code=503, detail="database unavailable") from exc
    return HealthResponse(status="ready")


# ---- redirect (registered last so it never shadows other routes) ----------------------------


def _record_click(app, code: str, referrer: str | None, user_agent: str | None) -> None:
    session = app.state.session_factory()
    try:
        s = app.state.settings
        LinkService(
            session,
            code_length=s.code_length,
            code_max_attempts=s.code_max_attempts,
            max_url_length=s.max_url_length,
        ).record_click(code, referrer=referrer, user_agent=user_agent)
    finally:
        session.close()


@redirect.get(
    "/{code}",
    status_code=302,
    responses={302: {"description": "Redirect to the target URL"}, **NOT_FOUND, **GONE},
)
def follow(
    code: str,
    request: Request,
    background: BackgroundTasks,
    service: LinkService = Depends(get_link_service),
) -> RedirectResponse:
    cache = request.app.state.cache
    cached = cache.get(code)
    if cached is not None:
        long_url, expires_at = cached
        if expires_at is not None and expires_at <= datetime.now(UTC):
            cache.invalidate(code)
            raise HTTPException(status_code=410, detail="link has expired")
    else:
        try:
            url = service.get(code)
        except LinkNotFoundError as exc:
            raise HTTPException(status_code=404, detail="link not found") from exc
        except LinkGoneError as exc:
            raise HTTPException(status_code=410, detail=str(exc)) from exc
        long_url = url.long_url
        cache.set(code, (long_url, as_utc(url.expires_at)))

    background.add_task(
        _record_click,
        request.app,
        code,
        request.headers.get("referer"),
        request.headers.get("user-agent"),
    )
    return RedirectResponse(long_url, status_code=302, headers={"Cache-Control": "no-store"})
